    detail: { q: 'According to the text, at about what age does a saguaro often grow its first arm?', a: 'around seventy years', w: ['about ten years', 'around two hundred years', 'about thirty years'] },
    fn: { i: 2, a: 'It draws a conclusion based on the facts about slow growth.', w: ['It describes the desert animals that live inside saguaros.', 'It gives an example of a cactus that grows very quickly.', 'It questions whether saguaros really grow slowly at all.'] },
    inf: { stem: 'Based on the text, a saguaro that is only a few centimeters tall is most likely ______', a: 'a young plant that is still growing.', w: ['an old plant that has stopped growing.', 'a plant that has already grown several arms.', 'a plant that grows faster than other saguaros.'] },
